)

Conditional

# Basic conditional constraint
@constraint(model, cond[i=1:5; i &gt; 2],
    x[i] &lt;= 10
)   # Only applies when i &gt; 2

# Multiple conditions
@constraint(model, cond2[i=1:10, j=1:10; i != j && i + j &lt;= 15],
    x[i,j] + x[j,i] &lt;= 1
)

